function connect(){
 const proto=location.protocol==='https:'?'wss:':'ws:';
 ws=new WebSocket(`${proto}//${location.host}`);
 ws.onmessage=(ev)=>{let d;try{d=JSON.parse(ev.data)}catch{return}if(d.type==='hello'){clientId=d.clientId;ws.send(JSON.stringify({type:'role',role:'listener',name:$('chatName')?.value||'Ouvinte'}))}if(d.type==='counts'){listenerCount=d.listeners||0;sampListenerCount=d.sampListeners||0;djPanelCount=d.djPanels||0;renderCounts()}if(d.type==='guest-error')notify(d.error||'Falha no acesso de convidado.','error');if(d.type==='guest-requests')loadGuestRequests();if(d.type==='rtc-join'&&broadcaster)createBroadcasterPeer(d.from);if(d.type==='rtc')handleRtc(d.from,d.payload);if(d.type==='state')renderState(d.state);if(d.type==='jobs-updated')loadJobs();if(d.type==='notice')notify(d.message||'A rádio foi atualizada.');if(d.type==='chat')addChat(d.message);if(d.type==='chat-error')notify(d.error||'Chat indisponível.','error')};
 ws.onclose=()=>setTimeout(connect,2500);
}
