async function trackPhotoAsDataUrl(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(Error('Não foi possível ler a foto.'));reader.onload=()=>{const img=new Image();img.onerror=()=>reject(Error('A foto selecionada não pôde ser aberta.'));img.onload=()=>{const max=900,scale=Math.min(1,max/Math.max(img.width,img.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));const ctx=canvas.getContext('2d');ctx.drawImage(img,0,0,canvas.width,canvas.height);let quality=.78,data=canvas.toDataURL('image/jpeg',quality);while(data.length>850000&&quality>.35){quality-=.08;data=canvas.toDataURL('image/jpeg',quality)}if(data.length>900000)return reject(Error('A foto ficou muito grande. Escolha uma imagem diferente.'));resolve(data)};img.src=String(reader.result)};reader.readAsDataURL(file)})}
