async function voteSong(index,type){const song=(currentState.mostPlayed||[])[index];if(!song)return;const key='gazetaVote:'+song.title+'|'+(song.artist||'');let previous='';try{previous=localStorage.getItem(key)||''}catch{}if(previous===type){notify('Você já registrou essa avaliação.','error');return}try{const r=await fetch('/api/songs/feedback',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({index,type,previous})});const d=await r.json();if(!r.ok)throw Error(d.error||'Não foi possível registrar o voto.');try{localStorage.setItem(key,type)}catch{} }catch(e){notify(e.message,'error')}}
